const drawerServices=`<details class="drawer-services"><summary>Explore all services</summary>${SERVICE_FAMILIES.map(f=>`<details class="drawer-service-group"><summary>${f.name}</summary><div class="drawer-service-links">${f.services.map(s=>`<a href="${serviceHref(s)}">${s.name}</a>`).join('')}</div></details>`).join('')}</details>`;
