const serviceMenu=$('#services-menu'),serviceToggle=$('#services-toggle');
function drawServiceMenu(){
 const family=SERVICE_FAMILIES[activeServiceFamily];
 const activeSlug=new URLSearchParams(location.search).get('slug')||'';
 serviceMenu.innerHTML=`<div class="service-menu-groups" role="group" aria-label="Service families">${SERVICE_FAMILIES.map((f,i)=>`<button type="button" class="${i===activeServiceFamily?'active':''}" aria-pressed="${i===activeServiceFamily}" data-family-index="${i}">${f.name}<span aria-hidden="true">→</span></button>`).join('')}</div>
 <div class="service-menu-detail"><div class="service-menu-heading"><div><h3>${family.label}</h3></div></div><div class="service-menu-items">${family.services.map(s=>`<a class="${s.slug===activeSlug?'active':''}" ${s.slug===activeSlug?'aria-current="page"':''} href="${serviceHref(s)}">${s.name}</a>`).join('')}</div><div class="service-menu-footer"><a href="service.html">Explore all services →</a><span>${family.name} · ${family.services.length} solutions</span></div></div>`;
}
function setServiceFamily(index){if(index===activeServiceFamily)return;activeServiceFamily=index;drawServiceMenu()}
let serviceMenuOpenedByHover=false;
function openServiceMenu(){const slug=new URLSearchParams(location.search).get('slug')||'';const activeIndex=SERVICE_FAMILIES.findIndex(f=>f.services.some(s=>s.slug===slug));if(activeIndex>=0)activeServiceFamily=activeIndex;drawServiceMenu();serviceMenu.classList.add('open');serviceToggle.setAttribute('aria-expanded','true')}
function closeServiceMenu(){serviceMenu.classList.remove('open');serviceToggle.setAttribute('aria-expanded','false');serviceMenuOpenedByHover=false}
drawServiceMenu();
serviceToggle.onclick=()=>{if(serviceMenuOpenedByHover){serviceMenuOpenedByHover=false;return}serviceToggle.getAttribute('aria-expanded')==='true'?closeServiceMenu():openServiceMenu()};
serviceToggle.parentElement.onmouseenter=()=>{if(!serviceMenu.classList.contains('open')){serviceMenuOpenedByHover=true;openServiceMenu()}};
serviceMenu.onpointerover=e=>{const b=e.target.closest('[data-family-index]');if(b)setServiceFamily(+b.dataset.familyIndex)};
serviceMenu.onclick=e=>{const b=e.target.closest('[data-family-index]');if(b)setServiceFamily(+b.dataset.familyIndex);if(e.target.closest('a'))closeServiceMenu()};
document.querySelector('nav').addEventListener('keydown',e=>{if(e.key==='Escape'){closeServiceMenu();serviceToggle.focus()}});
document.addEventListener('click',e=>{if(!e.target.closest('.nav-services')&&!e.target.closest('#services-menu'))closeServiceMenu()});
