let sl=null,catSel='All';
function initCases(){
 const cats=['All','Websites','SaaS','E-commerce','Dashboards'];
 const draw=()=>{$('#cats').innerHTML='<span class="mono" style="padding:var(--s2) 0">Categories</span>'+cats.map(c=>`<button class="${c===catSel?'on':''}" data-cat="${c}"><span>${c}</span><span>${c==='All'?CASES.length:CASES.filter(x=>x[2]===c).length}</span></button>`).join('');
  const l=$('#clist');l.style.opacity=0;setTimeout(()=>{l.innerHTML=CASES.filter(c=>catSel==='All'||c[2]===catSel).map(caseCard).join('');l.style.transition='opacity var(--t-med)';l.style.opacity=1;$$('.rv',l).forEach((e,i)=>{e.style.setProperty('--i',Math.min(i,7));requestAnimationFrame(()=>e.classList.add('in'))});observeReveals(l)},catSel===draw.last?0:80);draw.last=catSel;
  $$('[data-cat]').forEach(b=>b.onclick=()=>{catSel=b.dataset.cat;draw()})};draw.last=catSel;draw()}
function initTesti(){const q=$$('.tq'),d=$$('.dots button');if(!q.length)return;clearInterval(sl);let k=0;const set=n=>{k=(n+q.length)%q.length;q.forEach((e,i)=>e.classList.toggle('on',i===k));d.forEach((e,i)=>e.classList.toggle('on',i===k))};
 const restart=()=>{clearInterval(sl);sl=setInterval(()=>set(k+1),6500)};
 d.forEach(b=>b.onclick=()=>{set(+b.dataset.t);restart()});
 $$('[data-testimonial-step]').forEach(b=>b.onclick=()=>{set(k+Number(b.dataset.testimonialStep));restart()});
 restart()}
function initHeroCards(){const showcase=$('#hero-showcase');if(!showcase)return;
 $('[data-hero-direction]',showcase).onclick=()=>{showcase.dataset.direction=showcase.dataset.direction==='forward'?'reverse':'forward'};
 $('[data-hero-pause]',showcase).onclick=e=>{const paused=showcase.dataset.paused==='true';showcase.dataset.paused=String(!paused);e.currentTarget.textContent=paused?'Ⅱ':'▶';e.currentTarget.setAttribute('aria-label',paused?'Pause card movement':'Resume card movement')}}
function initDemo(){$('#demoForm').onsubmit=e=>{e.preventDefault();const f=e.target,d=Object.fromEntries(new FormData(f));
 if(!d.name.trim()||!/^\S+@\S+\.\S+$/.test(d.email)){alert('Please enter your name and a valid email.');return}
 d.at=new Date().toISOString();const l=ls.get('rd_leads',[]);l.unshift(d);ls.set('rd_leads',l);f.reset();$('#ok').style.display='block';setTimeout(()=>$('#ok').style.display='none',5000)}}
let authed=false;try{authed=sessionStorage.getItem('rd_auth')==='1'}catch(e){}
function initAdmin(){
 $('#loginForm').onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(e.target));if(d.u==='admin'&&d.p==='admin123'){authed=true;try{sessionStorage.setItem('rd_auth','1')}catch(x){}draw()}else $('#err').textContent='Wrong credentials.'};
 $('#logout').onclick=()=>{authed=false;try{sessionStorage.removeItem('rd_auth')}catch(e){}draw()};
 $('#clear').onclick=()=>{if(confirm('Delete all requests?')){ls.set('rd_leads',[]);draw()}};
 $('#csv').onclick=()=>{const l=ls.get('rd_leads',[]),k=['at','name','email','phone','company','interest','budget','msg'];const t=[k.join(',')].concat(l.map(r=>k.map(c=>'"'+String(r[c]||'').replace(/"/g,'""')+'"').join(','))).join('\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([t],{type:'text/csv'}));a.download='rdwavetech-leads.csv';a.click()};
 function draw(){$('#login').style.display=authed?'none':'block';$('#dash').style.display=authed?'block':'none';if(!authed)return;const l=ls.get('rd_leads',[]),wk=Date.now()-6048e5;
  $('#kpis').innerHTML=[['Total',l.length],['This week',l.filter(x=>new Date(x.at)>wk).length],['Websites',l.filter(x=>x.interest==='Website').length],['SaaS',l.filter(x=>x.interest==='SaaS product').length]].map(x=>`<div class="card"><span class="mono">${x[0]}</span><div class="price" style="color:var(--brand)">${x[1]}</div></div>`).join('');
  $('#rows').innerHTML=l.length?l.map((r,i)=>`<tr><td>${new Date(r.at).toLocaleDateString()}</td><td>${esc(r.name)}</td><td>${esc(r.email)}</td><td>${esc(r.phone)}</td><td>${esc(r.company)}</td><td>${esc(r.interest)}</td><td>${esc(r.budget)}</td><td>${esc((r.msg||'').slice(0,40))}</td><td><button class="btn sm ghost" data-d="${i}">Delete</button></td></tr>`).join(''):'<tr><td colspan="9">No demo requests yet.</td></tr>';
  $$('[data-d]').forEach(b=>b.onclick=()=>{const a=ls.get('rd_leads',[]);a.splice(+b.dataset.d,1);ls.set('rd_leads',a);draw()})}
 draw()}
const INIT={cases:initCases,demo:()=>{initDemo();initTesti()},home:()=>{initTesti();initHeroCards()},admin:initAdmin};

/* ---------- RENDER + REVEAL ---------- */
let io;
function split(r){$$('[data-split]',r).forEach(h=>{let i=0;const walk=n=>[...n.childNodes].forEach(c=>{if(c.nodeType===3){const f=document.createDocumentFragment();c.textContent.split(/(\s+)/).forEach(t=>{if(!t.trim()){f.append(t);return}const w=document.createElement('span');w.className='w';w.innerHTML='<span style="--i:'+i+++'">'+t+'</span>';f.append(w)});c.replaceWith(f)}else walk(c)});walk(h)})}
function count(el){if(el.dataset.counted)return;el.dataset.counted='true';const to=+el.dataset.count,t0=performance.now();(function s(t){const p=Math.min(1,(t-t0)/1100);el.textContent=Math.round(to*(1-Math.pow(1-p,4)));if(p<1)requestAnimationFrame(s)})(t0)}
function observeReveals(scope=document){if(io)$$('.rv',scope).forEach(e=>io.observe(e))}
function reveal(){
 $$('.stack,.bento,.plans,.steps4,.clist,.stats,.tgrid,.hero,.pagehero,.head').forEach(g=>$$(':scope > .rv',g).forEach((e,i)=>e.style.setProperty('--i',Math.min(i,7))));
 io=new IntersectionObserver(entries=>entries.forEach(entry=>{
  entry.target.classList.toggle('in',entry.isIntersecting);
  if(entry.isIntersecting)$$('[data-count]',entry.target).forEach(count);
 }),{threshold:.02,rootMargin:'0px 0px -24px 0px'});
 observeReveals(main);
 requestAnimationFrame(()=>main.classList.add('go'));
}
const BREADCRUMBS={
 services:[['Services','service.html']],process:[['How we work','how_we_work.html']],why:[['Why RD Wave','why_choose_us.html']],
 projects:[['Projects','projects.html']],demo:[['Book a demo','demo.html']],admin:[['Admin','admin.html']]
};
function normalizePageLinks(scope){
 $$('a[href^="#"]',scope).forEach(a=>{
  const key=a.getAttribute('href').slice(1);
  if(key.startsWith('service-')){const slug=key.slice(8);a.href=`individual_service.html?slug=${encodeURIComponent(slug)}`;return}
  if(key.startsWith('case-')){const slug=key.slice(5);a.href=`individual_project.html?slug=${encodeURIComponent(slug)}`;return}
  if(PAGE_HREF[key])a.href=PAGE_HREF[key];
 });
}
function showPage(){
 const page=document.body.dataset.page||'home',params=new URLSearchParams(location.search),slug=params.get('slug')||'';
 const service=page==='service-detail'?serviceBySlug(slug):null,project=page==='project-detail'?CASES.find(c=>c[0]===slug):null;
 const pageContent={
  home:P.home,services:P.services,process:P.process,why:P.why,projects:P.cases,demo:P.demo,admin:P.admin,
  'service-detail':()=>service?serviceDetail(service.slug):null,
  'project-detail':()=>project?detail(project[0]):null
 };
 let content=pageContent[page]?pageContent[page]():null;
 let currentLabel=service?.name||project?.[1]||TITLES[page]||'Page not found';
 if(!content){currentLabel='Page not found';content=`<div class="wrap"><section class="pagehero"><span class="tag">RD Wave Tech</span><h1 data-split>We couldn’t find that page.</h1><p class="rv">The link may have changed. Explore the services or projects to find what you need.</p><div class="cta-row"><a class="btn" href="service.html">Explore services</a><a class="btn ghost" href="projects.html">View projects</a></div></section></div>`}
 main.innerHTML=content;
 const crumbs=page==='service-detail'?[['Services','service.html'],[currentLabel,'']]:page==='project-detail'?[['Projects','projects.html'],[currentLabel,'']]:BREADCRUMBS[page]||[];
 if(page!=='home')main.insertAdjacentHTML('afterbegin',`<div class="wrap"><nav class="breadcrumbs" aria-label="Breadcrumb"><a href="index.html">Home</a>${crumbs.map(([label,href])=>`<span class="crumb-separator" aria-hidden="true">/</span>${href?`<a href="${href}">${label}</a>`:`<span class="crumb-current" aria-current="page">${label}</span>`}`).join('')}</nav></div>`);
 normalizePageLinks(main);
 split(main);
 const navPage=page==='service-detail'?'services':page==='project-detail'?'projects':page;
 $$('.links a,#drawer a.dl').forEach(a=>a.classList.toggle('on',a.getAttribute('href')===PAGE_HREF[navPage]));
 $('#services-toggle').classList.toggle('on',navPage==='services');
 document.title=`${currentLabel} — RD Wave Tech`;
 if(page!=='home')main.classList.add('page-enter');
 closeDrawer();closeServiceMenu();
 const initKey=page==='projects'?'cases':page;
 (INIT[initKey]||(()=>{}))();
 reveal();
}
showPage();

/* theme, drawer, popup */
$('#theme').onclick=()=>{const t=root.dataset.theme==='dark'?'light':'dark';root.dataset.theme=t;ls.set('rd_theme',t)};
function closeDrawer(){$('#drawer').classList.remove('open');$('#scrim').classList.remove('open')}
$('#burger').onclick=()=>{$('#drawer').classList.add('open');$('#scrim').classList.add('open')};$('#scrim').onclick=closeDrawer;
$('#drawer-close').onclick=closeDrawer;
const pop=$('#pop'),closePop=()=>{pop.classList.remove('show');pop.setAttribute('aria-hidden','true');document.body.classList.remove('popup-open')};
const openPop=()=>{pop.classList.add('show');pop.setAttribute('aria-hidden','false');document.body.classList.add('popup-open');$('#popX').focus()};
['popX','popNo','popGo'].forEach(i=>$('#'+i).addEventListener('click',closePop));
pop.onclick=e=>{if(e.target===pop)closePop()};
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&pop.classList.contains('show'))closePop()});
if(document.body.dataset.page==='home'){
 try{if(!sessionStorage.getItem('rd_pop')){setTimeout(()=>{openPop();sessionStorage.setItem('rd_pop','1')},1400)}}catch(e){setTimeout(openPop,1400)}
}
